_SURFACE_NAMES = {
    GeomAbs_Plane: "Plane",
    GeomAbs_Cylinder: "Cylinder",
    GeomAbs_Cone: "Cone",
    GeomAbs_Sphere: "Sphere",
    GeomAbs_Torus: "Torus",
    GeomAbs_BSplineSurface: "BSpline",
}


def _get_face_inventory(shape):
    explorer = TopExp_Explorer(shape.wrapped, TopAbs_FACE)
    faces = []
    while explorer.More():
        face = TopoDS.Face_s(explorer.Current())
        adaptor = BRepAdaptor_Surface(face)
        stype = adaptor.GetType()
        type_name = _SURFACE_NAMES.get(stype, f"Other({stype})")
        props = GProp_GProps()
        BRepGProp.SurfaceProperties_s(face, props)
        info = {"type": type_name, "area": props.Mass()}
        if stype == GeomAbs_Cylinder:
            info["diameter"] = adaptor.Cylinder().Radius() * 2
        elif stype == GeomAbs_Sphere:
            info["radius"] = adaptor.Sphere().Radius()
        elif stype == GeomAbs_Torus:
            info["major_r"] = adaptor.Torus().MajorRadius()
            info["minor_r"] = adaptor.Torus().MinorRadius()
        elif stype == GeomAbs_Cone:
            info["semi_angle_deg"] = math.degrees(adaptor.Cone().SemiAngle())
        faces.append(info)
        explorer.Next()
    faces.sort(key=lambda f: (f["type"], -f["area"]))
    return faces


_CURVE_NAMES = {
    GeomAbs_Line: "Line",
    GeomAbs_Circle: "Circle",
    GeomAbs_Ellipse: "Ellipse",
    GeomAbs_BSplineCurve: "BSpline",
}


def _get_edge_inventory(shape):
    explorer = TopExp_Explorer(shape.wrapped, TopAbs_EDGE)
    edges = []
    while explorer.More():
        edge = TopoDS.Edge_s(explorer.Current())
        adaptor = BRepAdaptor_Curve(edge)
        ctype = adaptor.GetType()
        type_name = _CURVE_NAMES.get(ctype, f"Other({int(ctype)})")
        length = GCPnts_AbscissaPoint.Length_s(adaptor)
        info = {"type": type_name, "length": length}
        if ctype == GeomAbs_Circle:
            info["radius"] = adaptor.Circle().Radius()
        edges.append(info)
        explorer.Next()
    edges.sort(key=lambda e: (e["type"], -e["length"]))
    return edges


def _cross_section_props(shape, axis_pos, plane_maker, uv_axes):
    # Return area, centroid, and 2D shape moments for a cross-section.
    _axis_idx = {"X": 1, "Y": 2, "Z": 3}
    u_idx = _axis_idx[uv_axes[0]]
    v_idx = _axis_idx[uv_axes[1]]
    zero = {"area": 0.0, "centroid_u": 0.0, "centroid_v": 0.0,
            "Iuu_2d": 0.0, "Ivv_2d": 0.0}
    plane = plane_maker(axis_pos)
    section = BRepAlgoAPI_Section(shape.wrapped, plane, False)
    section.ComputePCurveOn1(True)
    section.Approximation(True)
    section.Build()
    if not section.IsDone():
        return zero

    result_shape = section.Shape()
    edges_seq = TopTools_HSequenceOfShape()
    wires_seq = TopTools_HSequenceOfShape()
    edge_exp = TopExp_Explorer(result_shape, TopAbs_EDGE)
    while edge_exp.More():
        edges_seq.Append(edge_exp.Current())
        edge_exp.Next()
    if edges_seq.Length() == 0:
        return zero

    ShapeAnalysis_FreeBounds.ConnectEdgesToWires_s(
        edges_seq, 1e-4, False, wires_seq
    )
    total_area = 0.0
    total_cu = 0.0
    total_cv = 0.0
    total_Iuu = 0.0
    total_Ivv = 0.0
    for w_idx in range(1, wires_seq.Length() + 1):
        wire = TopoDS.Wire_s(wires_seq.Value(w_idx))
        try:
            face_maker = BRepBuilderAPI_MakeFace(plane, wire, True)
            if face_maker.IsDone():
                face_shape = face_maker.Face()
                face_props = GProp_GProps()
                BRepGProp.SurfaceProperties_s(face_shape, face_props)
                a = abs(face_props.Mass())
                com = face_props.CentreOfMass()
                u = getattr(com, uv_axes[0])()
                v = getattr(com, uv_axes[1])()
                total_area += a
                total_cu += u * a
                total_cv += v * a
                mat = face_props.MatrixOfInertia()
                total_Iuu += mat.Value(u_idx, u_idx)
                total_Ivv += mat.Value(v_idx, v_idx)
        except Exception:
            continue
    cu = total_cu / total_area if total_area > 1e-9 else 0.0
    cv = total_cv / total_area if total_area > 1e-9 else 0.0
    return {"area": total_area, "centroid_u": cu, "centroid_v": cv,
            "Iuu_2d": total_Iuu, "Ivv_2d": total_Ivv}


def _radial_distance(shape, origin, direction, max_r=20.0):
    line = gp_Lin(origin, direction)
    intersector = IntCurvesFace_ShapeIntersector()
    intersector.Load(shape.wrapped, 1e-6)
    intersector.PerformNearest(line, 0.0, max_r)
    if intersector.NbPnt() > 0:
        pt = intersector.Pnt(1)
        dx = pt.X() - origin.X()
        dy = pt.Y() - origin.Y()
        dz = pt.Z() - origin.Z()
        return math.sqrt(dx * dx + dy * dy + dz * dz)
    return None


# ═══════════════════════════════════════════════════════════
# Hausdorff distance helpers
# (copied verbatim from cad_fingerprint.hausdorff / .analyze)
# ═══════════════════════════════════════════════════════════

def decode_mesh(payload: dict) -> tuple[list, list]:
    """Decode an :func:`encode_mesh` payload back into (vertices, triangles)."""
    if payload and payload.get("truncated"):
        raise ValueError(
            "this fingerprint's surface mesh was truncated for display; "
            "re-run the analysis with --json to write the full mesh"
        )
    if not payload or not payload.get("vertex_count"):
        return [], []
    lo = payload["bbox_min"]
    hi = payload["bbox_max"]
    scale = [(hi[a] - lo[a]) / 65535.0 if hi[a] > lo[a] else 0.0
             for a in range(3)]

    vbuf = zlib.decompress(base64.b64decode(payload["vertices"]))
    raw = struct.unpack(f"<{len(vbuf) // 2}H", vbuf)
    vertices = [
        (lo[0] + raw[i] * scale[0],
         lo[1] + raw[i + 1] * scale[1],
         lo[2] + raw[i + 2] * scale[2])
        for i in range(0, len(raw), 3)
    ]

    tbuf = zlib.decompress(base64.b64decode(payload["triangles"]))
    if payload.get("index_bits", 16) == 16:
        flat = struct.unpack(f"<{len(tbuf) // 2}H", tbuf)
    else:
        flat = struct.unpack(f"<{len(tbuf) // 4}I", tbuf)
    triangles = [flat[i:i + 3] for i in range(0, len(flat), 3)]
    return vertices, triangles


def _point_triangle_distance2(p, a, b, c) -> float:
    """Squared distance from point p to triangle (a, b, c).

    Voronoi-region algorithm (Ericson, *Real-Time Collision Detection*):
    classify p against the triangle's vertex/edge/face regions, then
    project onto whichever feature is closest.
    """
    abx, aby, abz = b[0] - a[0], b[1] - a[1], b[2] - a[2]
    acx, acy, acz = c[0] - a[0], c[1] - a[1], c[2] - a[2]
    apx, apy, apz = p[0] - a[0], p[1] - a[1], p[2] - a[2]

    d1 = abx * apx + aby * apy + abz * apz
    d2 = acx * apx + acy * apy + acz * apz
    if d1 <= 0.0 and d2 <= 0.0:
        return apx * apx + apy * apy + apz * apz

    bpx, bpy, bpz = p[0] - b[0], p[1] - b[1], p[2] - b[2]
    d3 = abx * bpx + aby * bpy + abz * bpz
    d4 = acx * bpx + acy * bpy + acz * bpz
    if d3 >= 0.0 and d4 <= d3:
        return bpx * bpx + bpy * bpy + bpz * bpz

    vc = d1 * d4 - d3 * d2
    if vc <= 0.0 and d1 >= 0.0 and d3 <= 0.0:
        denom = d1 - d3
        v = d1 / denom if denom != 0.0 else 0.0
        dx, dy, dz = apx - v * abx, apy - v * aby, apz - v * abz
        return dx * dx + dy * dy + dz * dz

    cpx, cpy, cpz = p[0] - c[0], p[1] - c[1], p[2] - c[2]
    d5 = abx * cpx + aby * cpy + abz * cpz
    d6 = acx * cpx + acy * cpy + acz * cpz
    if d6 >= 0.0 and d5 <= d6:
        return cpx * cpx + cpy * cpy + cpz * cpz

    vb = d5 * d2 - d1 * d6
    if vb <= 0.0 and d2 >= 0.0 and d6 <= 0.0:
        denom = d2 - d6
        w = d2 / denom if denom != 0.0 else 0.0
        dx, dy, dz = apx - w * acx, apy - w * acy, apz - w * acz
        return dx * dx + dy * dy + dz * dz

    va = d3 * d6 - d5 * d4
    if va <= 0.0 and (d4 - d3) >= 0.0 and (d5 - d6) >= 0.0:
        denom = (d4 - d3) + (d5 - d6)
        w = (d4 - d3) / denom if denom != 0.0 else 0.0
        dx = p[0] - (b[0] + w * (c[0] - b[0]))
        dy = p[1] - (b[1] + w * (c[1] - b[1]))
        dz = p[2] - (b[2] + w * (c[2] - b[2]))
        return dx * dx + dy * dy + dz * dz

    denom = va + vb + vc
    if denom == 0.0:  # degenerate triangle — fall back to vertex a
        return apx * apx + apy * apy + apz * apz
    v = vb / denom
    w = vc / denom
    dx = apx - (v * abx + w * acx)
    dy = apy - (v * aby + w * acy)
    dz = apz - (v * abz + w * acz)
    return dx * dx + dy * dy + dz * dz


def _mesh_area(tris) -> float:
    """Total area of a list of (a, b, c) vertex triples."""
    total = 0.0
    for a, b, c in tris:
        ux, uy, uz = b[0] - a[0], b[1] - a[1], b[2] - a[2]
        vx, vy, vz = c[0] - a[0], c[1] - a[1], c[2] - a[2]
        nx = uy * vz - uz * vy
        ny = uz * vx - ux * vz
        nz = ux * vy - uy * vx
        total += 0.5 * math.sqrt(nx * nx + ny * ny + nz * nz)
    return total


class TriangleGrid:
    """Uniform spatial grid over a triangle mesh for nearest-surface queries.

    Each triangle is registered in every cell its bounding box touches.
    A query walks outward in cubic shells around the query point's cell and
    stops once the best distance found is closer than any unvisited shell
    could possibly be.
    """

    def __init__(self, vertices, triangles, target_per_cell: float = 3.0):
        self.tris = [
            (vertices[i], vertices[j], vertices[k]) for i, j, k in triangles
        ]
        xs = [v[0] for v in vertices]
        ys = [v[1] for v in vertices]
        zs = [v[2] for v in vertices]
        if not xs:
            self.cells = {}
            self.cell = 1.0
            self.dims = (1, 1, 1)
            self.origin = (0.0, 0.0, 0.0)
            return
        pad = 1e-6
        self.origin = (min(xs) - pad, min(ys) - pad, min(zs) - pad)
        span = (
            max(xs) - min(xs) + 2 * pad,
            max(ys) - min(ys) + 2 * pad,
            max(zs) - min(zs) + 2 * pad,
        )
        # Size the cell from surface area, not bounding-box volume: the
        # triangles form a 2D sheet inside the box, and a flat part has no
        # volume to divide by at all. Occupied cells go as area / cell², so
        # cell = sqrt(target_per_cell * area / triangle count) puts roughly
        # target_per_cell triangles in each.
        area = _mesh_area(self.tris)
        count = max(len(self.tris), 1)
        if area > 0.0:
            self.cell = math.sqrt(target_per_cell * area / count)
        else:
            self.cell = max(span) / 8.0
        # Never so fine that one triangle spans a huge number of cells.
        self.cell = max(self.cell, max(span) / 512.0, 1e-9)
        self.dims = tuple(max(int(s / self.cell) + 1, 1) for s in span)
        self.max_ring = max(self.dims)

        cells = {}
        ox, oy, oz = self.origin
        c = self.cell
        for idx, (a, b, cc) in enumerate(self.tris):
            i0 = int((min(a[0], b[0], cc[0]) - ox) / c)
            i1 = int((max(a[0], b[0], cc[0]) - ox) / c)
            j0 = int((min(a[1], b[1], cc[1]) - oy) / c)
            j1 = int((max(a[1], b[1], cc[1]) - oy) / c)
            k0 = int((min(a[2], b[2], cc[2]) - oz) / c)
            k1 = int((max(a[2], b[2], cc[2]) - oz) / c)
            for i in range(i0, i1 + 1):
                for j in range(j0, j1 + 1):
                    for k in range(k0, k1 + 1):
                        cells.setdefault((i, j, k), []).append(idx)
        self.cells = cells

    def nearest_distance(self, p) -> float:
        """Distance from p to the closest point on the mesh surface."""
        if not self.tris:
            return float("inf")
        c = self.cell
        ox, oy, oz = self.origin
        ci = int((p[0] - ox) / c)
        cj = int((p[1] - oy) / c)
        ck = int((p[2] - oz) / c)
        inside = (
            0 <= ci < self.dims[0]
            and 0 <= cj < self.dims[1]
            and 0 <= ck < self.dims[2]
        )
        if not inside:
            # Outside the mesh's grid: the shell bound below assumes p sits
            # in its own cell, so fall back to an exhaustive scan. Only
            # happens for points well clear of the reference surface.
            best2 = float("inf")
            for tri in self.tris:
                d2 = _point_triangle_distance2(p, tri[0], tri[1], tri[2])
                if d2 < best2:
                    best2 = d2
            return math.sqrt(best2)

        best2 = float("inf")
        checked = set()
        cells = self.cells
        tris = self.tris
        ring = 0
        while ring <= self.max_ring:
            for i in range(ci - ring, ci + ring + 1):
                for j in range(cj - ring, cj + ring + 1):
                    for k in range(ck - ring, ck + ring + 1):
                        # only the shell surface, inner cells already done
                        if ring and (
                            abs(i - ci) != ring
                            and abs(j - cj) != ring
                            and abs(k - ck) != ring
                        ):
                            continue
                        for idx in cells.get((i, j, k), ()):
                            if idx in checked:
                                continue
                            checked.add(idx)
                            tri = tris[idx]
                            d2 = _point_triangle_distance2(
                                p, tri[0], tri[1], tri[2]
                            )
                            if d2 < best2:
                                best2 = d2
            # A triangle first appearing at shell ring+1 is at least
            # ring*cell away from p, so this bound is safe.
            if best2 <= (ring * c) ** 2:
                break
            ring += 1
        return math.sqrt(best2)


def _radical_inverse(n: int, base: int) -> float:
    """Van der Corput radical inverse — a deterministic low-discrepancy value."""
    result = 0.0
    inv = 1.0 / base
    f = inv
    while n > 0:
        result += (n % base) * f
        n //= base
        f *= inv
    return result


def sample_mesh_points(vertices, triangles, count: int) -> list:
    """Sample ``count`` points spread over the mesh surface, area-weighted.

    Deterministic: triangles are picked by stratifying the cumulative-area
    axis and barycentric coordinates come from a Halton sequence, so no
    random number generator is involved and results are reproducible across
    machines and Python versions.
    """
    if not triangles or count <= 0:
        return []
    cumulative = []
    total = 0.0
    for i, j, k in triangles:
        a, b, c = vertices[i], vertices[j], vertices[k]
        ux, uy, uz = b[0] - a[0], b[1] - a[1], b[2] - a[2]
        vx, vy, vz = c[0] - a[0], c[1] - a[1], c[2] - a[2]
        nx = uy * vz - uz * vy
        ny = uz * vx - ux * vz
        nz = ux * vy - uy * vx
        total += 0.5 * math.sqrt(nx * nx + ny * ny + nz * nz)
        cumulative.append(total)
    if total <= 0.0:
        return []

    points = []
    for n in range(count):
        target = (n + 0.5) / count * total
        t_idx = min(bisect.bisect_left(cumulative, target), len(triangles) - 1)
        i, j, k = triangles[t_idx]
        a, b, c = vertices[i], vertices[j], vertices[k]
        r1 = _radical_inverse(n + 1, 2)
        r2 = _radical_inverse(n + 1, 3)
        s = math.sqrt(r1)
        w0 = 1.0 - s
        w1 = s * (1.0 - r2)
        w2 = s * r2
        points.append((
            a[0] * w0 + b[0] * w1 + c[0] * w2,
            a[1] * w0 + b[1] * w1 + c[1] * w2,
            a[2] * w0 + b[2] * w1 + c[2] * w2,
        ))
    return points


def _distance_stats(distances: list) -> dict:
    """max / mean / rms / 95th percentile of a distance list."""
    if not distances:
        return {"max": 0.0, "mean": 0.0, "rms": 0.0, "p95": 0.0}
    n = len(distances)
    ordered = sorted(distances)
    return {
        "max": ordered[-1],
        "mean": sum(ordered) / n,
        "rms": math.sqrt(sum(d * d for d in ordered) / n),
        "p95": ordered[min(int(0.95 * n), n - 1)],
    }


def hausdorff_distance(mesh_a, mesh_b, samples: int = 2000) -> dict:
    """Two-sided approximate Hausdorff distance between two meshes.

    Args:
        mesh_a: (vertices, triangles) of the reference mesh.
        mesh_b: (vertices, triangles) of the mesh being compared.
        samples: points sampled per direction; must be positive.

    Returns a dict with ``forward`` (A→B), ``backward`` (B→A) and combined
    ``hausdorff`` / ``mean`` / ``rms`` / ``p95`` values, all in model units.
    """
    if samples < 1:
        # Zero samples would report a flawless match for any pair of shapes.
        raise ValueError(f"samples must be at least 1, got {samples}")

    va, ta = mesh_a
    vb, tb = mesh_b
    grid_a = TriangleGrid(va, ta)
    grid_b = TriangleGrid(vb, tb)

    pts_a = sample_mesh_points(va, ta, samples)
    pts_b = sample_mesh_points(vb, tb, samples)
    fwd = [grid_b.nearest_distance(p) for p in pts_a]
    bwd = [grid_a.nearest_distance(p) for p in pts_b]

    f_stats = _distance_stats(fwd)
    b_stats = _distance_stats(bwd)
    both = _distance_stats(fwd + bwd)
    return {
        "samples": samples,
        "forward": f_stats,
        "backward": b_stats,
        "hausdorff": max(f_stats["max"], b_stats["max"]),
        "mean": both["mean"],
        "rms": both["rms"],
        "p95": both["p95"],
    }


def _triangulate(shape, deflection, angular_deflection, remesh):
    """Return (vertices, triangles) for a shape, meshing it first if asked.

    Meshing writes a triangulation into the shape, so a copy is meshed and
    the caller's shape is left exactly as it was — generated tests must not
    mutate the fixture they are handed.
    """
    from OCP.BRep import BRep_Tool
    from OCP.BRepBuilderAPI import BRepBuilderAPI_Copy
    from OCP.BRepMesh import BRepMesh_IncrementalMesh
    from OCP.BRepTools import BRepTools
    from OCP.TopLoc import TopLoc_Location

    target = shape.wrapped
    if remesh:
        target = BRepBuilderAPI_Copy(target).Shape()
        BRepTools.Clean_s(target)
        BRepMesh_IncrementalMesh(
            target, deflection, False, angular_deflection, True
        )

    vertices: list = []
    triangles: list = []
    explorer = TopExp_Explorer(target, TopAbs_FACE)
    while explorer.More():
        face = TopoDS.Face_s(explorer.Current())
        loc = TopLoc_Location()
        tri = BRep_Tool.Triangulation_s(face, loc)
        if tri is None:
            explorer.Next()
            continue
        transform = loc.Transformation()
        flipped = face.Orientation() == TopAbs_REVERSED
        offset = len(vertices)
        for i in range(1, tri.NbNodes() + 1):
            pnt = tri.Node(i).Transformed(transform)
            vertices.append((pnt.X(), pnt.Y(), pnt.Z()))
        for i in range(1, tri.NbTriangles() + 1):
            n1, n2, n3 = tri.Triangle(i).Get()
            if flipped:
                n2, n3 = n3, n2
            triangles.append((offset + n1 - 1, offset + n2 - 1, offset + n3 - 1))
        explorer.Next()
    return vertices, triangles


_HAUSDORFF_CACHE = {}


def _shape_signature(shape):
    """Cheap key identifying a shape's geometry (not its object identity).

    Volume and envelope alone would collide on exactly the differences
    this test exists to catch — a mirrored part, or a feature moved
    within the same envelope — so the centre of mass and surface area
    go in too.
    """
    volume = GProp_GProps()
    BRepGProp.VolumeProperties_s(shape.wrapped, volume)
    surface = GProp_GProps()
    BRepGProp.SurfaceProperties_s(shape.wrapped, surface)
    com = volume.CentreOfMass()
    bb = shape.bounding_box()
    return (
        round(volume.Mass(), 9), round(surface.Mass(), 9),
        round(com.X(), 9), round(com.Y(), 9), round(com.Z(), 9),
        round(bb.min.X, 9), round(bb.min.Y, 9), round(bb.min.Z, 9),
        round(bb.max.X, 9), round(bb.max.Y, 9), round(bb.max.Z, 9),
    )


def _hausdorff_vs_reference(shape):
    """Two-sided surface deviation between `shape` and the reference mesh.

    Keyed on the shape's geometry rather than on `id()`, because a
    function-scoped pytest fixture hands each test a freshly built part —
    the max and mean tests would otherwise pay for the whole measurement
    twice.
    """
    key = _shape_signature(shape)
    if key in _HAUSDORFF_CACHE:
        return _HAUSDORFF_CACHE[key]
    reference = decode_mesh(REF_MESH)
    deflection = REF_MESH["deflection"]
    angular = REF_MESH["angular_deflection"]
    actual = _triangulate(shape, deflection, angular, True)
    # The reference mesh was capped; cap this one too, or a part with far
    # more detail makes these pure-Python distance queries crawl.
    attempts = 0
    while len(actual[1]) > REF_MESH["max_triangles"] and attempts < 6:
        deflection *= 1.7
        angular = min(angular * 1.3, 1.0)
        attempts += 1
        actual = _triangulate(shape, deflection, angular, True)
    result = hausdorff_distance(reference, actual, HAUSDORFF_SAMPLES)
    # Coarsening costs accuracy, so the floor has to move with it. Chord
    # error scales with the deflection the mesh was built at, which is
    # all this needs: reading it off the candidate's own facets would let
    # the part under test widen the tolerance it is judged by.
    candidate_error = REF_MESH["candidate_resolution"] * (
        deflection / REF_MESH["deflection"]
    )
    result["floor"] = 2.0 * (REF_MESH["resolution"] + candidate_error)
    result["deflection"] = deflection
    if len(_HAUSDORFF_CACHE) > 4:
        _HAUSDORFF_CACHE.clear()
    _HAUSDORFF_CACHE[key] = result
    return result


# ═══════════════════════════════════════════════════════════
# Tests for Grip
# ═══════════════════════════════════════════════════════════

class TestGlobalProperties:
    """Volume, surface area, bounding box, center of mass."""

    def test_volume(self, part_under_test):
        vol_props = GProp_GProps()
        BRepGProp.VolumeProperties_s(part_under_test.wrapped, vol_props)
        vol = vol_props.Mass()
        pct = abs(vol - REF_VOLUME) / REF_VOLUME * 100
        direction = 'larger' if vol > REF_VOLUME else 'smaller'
        assert pct / 100 < 0.01, (
            f"Volume {vol:.4f} is {direction} than ref {REF_VOLUME} by {abs(vol - REF_VOLUME):.2f} mm³ ({pct:.1f}%) — adjust overall dimensions"
        )

    def test_surface_area(self, part_under_test):
        props = GProp_GProps()
        BRepGProp.SurfaceProperties_s(part_under_test.wrapped, props)
        area = props.Mass()
        pct = abs(area - REF_SURFACE_AREA) / REF_SURFACE_AREA * 100
        direction = 'larger' if area > REF_SURFACE_AREA else 'smaller'
        assert pct / 100 < 0.02, (
            f"Surface area {area:.4f} is {direction} than ref {REF_SURFACE_AREA} ({pct:.1f}% off) — check feature dimensions"
        )

    def test_bounding_box(self, part_under_test):
        bb = part_under_test.bounding_box()
        tol = 0.1
        assert abs(bb.min.X - REF_BBOX_MIN[0]) < tol, "BBox min X mismatch"
        assert abs(bb.max.X - REF_BBOX_MAX[0]) < tol, "BBox max X mismatch"
        assert abs(bb.min.Y - REF_BBOX_MIN[1]) < tol, "BBox min Y mismatch"
        assert abs(bb.max.Y - REF_BBOX_MAX[1]) < tol, "BBox max Y mismatch"
        assert abs(bb.min.Z - REF_BBOX_MIN[2]) < tol, "BBox min Z mismatch"
        assert abs(bb.max.Z - REF_BBOX_MAX[2]) < tol, "BBox max Z mismatch"

    def test_center_of_mass(self, part_under_test):
        props = GProp_GProps()
        BRepGProp.VolumeProperties_s(part_under_test.wrapped, props)
        com = props.CentreOfMass()
        for i, (actual, ref) in enumerate(zip(
            (com.X(), com.Y(), com.Z()), REF_CENTER_OF_MASS)):
            assert abs(actual - ref) < 0.2, (
                f"CoM axis {i}: {actual:.4f} vs ref {ref:.4f}"
            )


class TestMomentsOfInertia:
    """Inertia tensor — very sensitive to mass distribution."""

    def test_principal_moments(self, part_under_test):
        props = GProp_GProps()
        BRepGProp.VolumeProperties_s(part_under_test.wrapped, props)
        mat = props.MatrixOfInertia()
        for key, (r, c) in [("Ixx", (1,1)), ("Iyy", (2,2)), ("Izz", (3,3))]:
            actual = mat.Value(r, c)
            ref = REF_INERTIA[key]
            if abs(ref) > 1e-6:
                pct = abs(actual - ref) / abs(ref) * 100
                assert pct / 100 < 0.02, (
                    f"{key}: {actual:.4f} vs ref {ref:.4f} ({pct:.1f}% off) — mass distribution differs"
                )

    def test_off_diagonal_moments(self, part_under_test):
        props = GProp_GProps()
        BRepGProp.VolumeProperties_s(part_under_test.wrapped, props)
        mat = props.MatrixOfInertia()
        for key, (r, c) in [("Ixy", (1,2)), ("Ixz", (1,3)), ("Iyz", (2,3))]:
            actual = mat.Value(r, c)
            ref = REF_INERTIA[key]
            tol = max(abs(ref) * 0.02, 1.0)
            assert abs(actual - ref) < tol, (
                f"{key}: {actual:.4f} vs ref {ref:.4f} — part may be rotated or asymmetric"
            )


class TestCrossSections:
    """Cross-sectional area and centroid at 24 positions along Z."""

    _plane_maker = staticmethod(lambda v: gp_Pln(gp_Pnt(0, 0, v), gp_Dir(0, 0, 1)))
    _uv_axes = ("X", "Y")

    @pytest.mark.parametrize("ref", REF_CROSS_SECTIONS,
        ids=[f"Z={cs['position']}" for cs in REF_CROSS_SECTIONS])
    def test_cross_section_area(self, part_under_test, ref):
        props = _cross_section_props(part_under_test, ref["position"], self._plane_maker, self._uv_axes)
        area = props["area"]
        ref_area = ref["area"]
        if ref_area < 0.01:  # near-zero slice
            assert area < 0.5, f"Expected ~0 area at pos={ref['position']}, got {area:.4f}"
        else:
            pct = abs(area - ref_area) / ref_area * 100
            direction = 'too large' if area > ref_area else 'too small'
            assert pct / 100 < 0.03, (
                f"Area at Z={ref['position']}: {area:.4f} vs ref {ref_area:.4f} "
                f"({pct:.1f}% {direction}) — adjust radius/fillet at this position"
            )

    @pytest.mark.parametrize("ref", REF_CROSS_SECTIONS,
        ids=[f"Z={cs['position']}" for cs in REF_CROSS_SECTIONS])
    def test_cross_section_centroid(self, part_under_test, ref):
        ref_area = ref["area"]
        if ref_area < 0.01:
            pytest.skip("near-zero area — centroid meaningless")
        props = _cross_section_props(part_under_test, ref["position"], self._plane_maker, self._uv_axes)
        for ref_key, prop_key in [("centroid_x", "centroid_u"), ("centroid_y", "centroid_v")]:
            actual = props[prop_key]
            ref_val = ref[ref_key]
            diff = actual - ref_val
            assert abs(diff) < 0.2, (
                f"Centroid {ref_key} at Z={ref['position']}: {actual:.4f} vs ref {ref_val:.4f} "
                f"(shifted {'positive' if diff > 0 else 'negative'} by {abs(diff):.3f}mm) — check alignment"
            )

    @pytest.mark.parametrize("ref", REF_CROSS_SECTIONS,
        ids=[f"Z={cs['position']}" for cs in REF_CROSS_SECTIONS])
    def test_cross_section_shape(self, part_under_test, ref):
        """2D moments capture cross-section shape, not just area."""
        ref_area = ref["area"]
        if ref_area < 0.01:
            pytest.skip("near-zero area — shape moments meaningless")
        props = _cross_section_props(part_under_test, ref["position"], self._plane_maker, self._uv_axes)
        for ref_key, prop_key in [("Ixx_2d", "Iuu_2d"), ("Iyy_2d", "Ivv_2d")]:
            ref_val = ref.get(ref_key, 0.0)
            if abs(ref_val) < 0.01:
                continue
            actual = props[prop_key]
            pct = abs(actual - ref_val) / abs(ref_val) * 100
            assert pct / 100 < 0.05, (
                f"Shape moment {ref_key} at Z={ref['position']}: {actual:.4f} vs ref {ref_val:.4f} "
                f"({pct:.1f}% off) — cross-section shape differs"
            )


class TestRadialProfile:
    """Radial distance from axis at 15 positions × 12 angles."""

    @pytest.mark.parametrize("ref", REF_RADIAL_PROFILE,
        ids=[f"Z={rp['position']}" for rp in REF_RADIAL_PROFILE])
    def test_radial_profile(self, part_under_test, ref):
        pos = ref["position"]
        for deg_str, ref_r in ref["radii"].items():
            deg = float(deg_str)
            if ref_r is None:
                continue
            origin = gp_Pnt(0, 0, pos)
            direction = gp_Dir(math.cos(math.radians(deg)), math.sin(math.radians(deg)), 0)
            actual_r = _radial_distance(part_under_test, origin, direction)
            assert actual_r is not None, (
                f"No intersection at Z={pos}, angle={deg}°"
            )
            hint = 'excess' if actual_r > ref_r else 'missing'
            assert abs(actual_r - ref_r) < 0.15, (
                f"Radial at Z={pos} angle={deg}°: {actual_r:.4f} vs ref {ref_r:.4f} — {hint} material"
            )


class TestSurfaceDeviation:
    """Hausdorff distance — worst-case point-to-surface deviation.

    Volume, area and cross-sections are aggregates: they can all agree
    while the surface is locally wrong. These tests sample points on both
    surfaces and measure how far each one is from the other surface.
    """

    def test_max_deviation(self, part_under_test):
        """No sampled point on either surface is further than the tolerance.

        This is a sampled estimate, not a proof: with HAUSDORFF_SAMPLES
        points per direction against 7724
        reference triangles, a defect confined to a few triangles can be
        missed. Raise --hausdorff-samples to sample the surface harder.
        """
        result = _hausdorff_vs_reference(part_under_test)
        tolerance = max(0.3, result["floor"])
        fwd = result["forward"]["max"]
        bwd = result["backward"]["max"]
        side = "missing material" if fwd > bwd else "excess material"
        assert result["hausdorff"] < tolerance, (
            f"Hausdorff distance {result['hausdorff']:.4f}mm exceeds "
            f"{tolerance:.4f}mm over {result['samples']} "
            f"samples/direction (ref→part {fwd:.4f}, part→ref "
            f"{bwd:.4f}, 95th pct {result['p95']:.4f}) — worst area "
            f"looks like {side}"
        )

    def test_mean_deviation(self, part_under_test):
        """The surfaces agree closely on average, not just at worst case."""
        result = _hausdorff_vs_reference(part_under_test)
        tolerance = max(0.05, result["floor"] / 4.0)
        assert result["mean"] < tolerance, (
            f"Mean surface deviation {result['mean']:.4f}mm exceeds "
            f"{tolerance:.4f}mm (RMS {result['rms']:.4f}, 95th pct "
            f"{result['p95']:.4f}) — the whole surface is off, not just "
            f"a local feature"
        )


class TestBuildQuality:
    """Solid validity, watertight check, single body."""

    def test_single_solid(self, part_under_test):
        """Result must be a single solid (not split by failed booleans)."""
        from OCP.TopAbs import TopAbs_SOLID
        exp = TopExp_Explorer(part_under_test.wrapped, TopAbs_SOLID)
        count = 0
        while exp.More():
            count += 1
            exp.Next()
        assert count == 1, (
            f"Expected 1 solid(s), got {count}"
        )

    def test_no_free_edges(self, part_under_test):
        """No free edges — the solid must be watertight."""
        from OCP.ShapeAnalysis import ShapeAnalysis_FreeBounds
        fb = ShapeAnalysis_FreeBounds(part_under_test.wrapped)
        open_wires = fb.GetOpenWires()
        exp = TopExp_Explorer(open_wires, TopAbs_EDGE)
        free_count = 0
        while exp.More():
            free_count += 1
            exp.Next()
        assert free_count == 0, (
            f"Found {free_count} free edge(s) — solid is not watertight"
        )

    def test_shape_valid(self, part_under_test):
        """OCCT validity check — no degenerate or corrupt geometry."""
        from OCP.BRepCheck import BRepCheck_Analyzer
        analyzer = BRepCheck_Analyzer(part_under_test.wrapped)
        assert analyzer.IsValid(), "BRepCheck_Analyzer reports invalid geometry"
